const keys = ["Q", "W", "E", "R", "A", "S", "D", "F", "Z", "X", "C", "V", "1", "2", "3", "4"];
const colors = ["#262626", "#2e2e2e", "#363636", "#3e3e3e", "#464646", "#4e4e4e", "#565656", "#5e5e5e", "#666666", "#6e6e6e", "#767676", "#7e7e7e", "#868686", "#8e8e8e", "#969696", "#9e9e9e"];
const pads = Array.from({ length: 16 }, (_, index) => ({
  id: index + 1,
  label: "",
  key: keys[index],
  color: colors[index],
  mode: "oneshot",
  volume: 0.8,
  sampleId: null,
  sliceId: null,
  schemaVersion: 2,
  triggerMode: "trigger",
  mappingMode: "single",
  launchQuantize: "off",
  stopQuantize: "off",
  chokeGroup: null,
  muteGroup: null,
  linkGroup: null,
  midi: { note: null, channel: null },
  layerIds: [],
  sampleRegion: { start: 0, end: 1, loopStart: 0, loopEnd: 1, reverse: false },
  pitchCents: 0,
  timeStretch: 1,
  attack: 0.005,
  release: 0.015,
  pan: 0,
  filter: { type: "lowpass", frequency: 20000, q: 0 },
  effectSends: { reverb: 0, delay: 0 },
  sampleProcessing: { zoom: 1, fadeIn: 0.005, fadeOut: 0.015, normalize: false },
}));
const normalizedPads = pads.map((pad) => ({
  ...pad,
  midi: { note: 0, channel: 0 },
  filter: { ...pad.filter, q: 0.0001 },
}));

